arguments.command:
python3 - <<'EOF'
import os,signal,re
for p in os.listdir('/proc'):
    if p.isdigit():
        try: c=open(f'/proc/{p}/cmdline','rb').read().decode().replace('\0',' ')
        except: continue
        if 'pypiserver' in c:
            print('kill',p,c); os.kill(int(p),signal.SIGKILL)
EOF
sleep 1; curl -s -m 3 -o /dev/null -w "after-kill:%{http_code}\n" http://localhost:8080/simple/

